1056		buf += i;
1057		length -= i;
1058	
1059		if (length <= 0 || (i = usb_make_path(usb_dev, buf, length)) < 0)
1060			goto bind;
1061	
1062		buf += i;
1063		length -= i;
1064	
1065		snprintf(buf, length, ")");
